"""Generate test/ArmData.sol from the arm record CSVs.

Packs each arm's 365 daily netSpend values as int32 big-endian so the Solidity
differential test can replay real data without a 365-line literal array.
Re-run after regenerating the CSVs.
"""
import csv, io

ARMS = ("B0", "B1", "B2")


def encode(values):
    out = bytearray()
    for v in values:
        out += int(v).to_bytes(4, "big", signed=True)
    return out.hex()


def main():
    lines = [
        "// SPDX-License-Identifier: MIT",
        "// GENERATED by differential/gen_arm_data.py -- do not edit by hand.",
        "// Daily netSpend (milli-USD, signed) per arm, int32 big-endian, 4 bytes per day.",
        "pragma solidity ^0.8.23;",
        "",
        "library ArmData {",
    ]
    for arm in ARMS:
        vals = [int(r["spendMilliUsd"]) for r in csv.DictReader(open(f"records_{arm}.csv"))]
        assert len(vals) == 365, f"{arm}: expected 365 rows, got {len(vals)}"
        lines += [
            f"    // {arm}: 365 days, min {min(vals)}, max {max(vals)}, "
            f"{sum(1 for v in vals if v < 0)} negative",
            f'    bytes internal constant {arm}_DATA = hex"{encode(vals)}";',
            "",
        ]
    lines += [
        "    function dayCount() internal pure returns (uint256) { return 365; }",
        "",
        "    /// @notice Decode day `i` from a packed int32 big-endian blob.",
        "    function at(bytes memory blob, uint256 i) internal pure returns (int256) {",
        "        uint256 o = i * 4;",
        "        uint32 raw = (uint32(uint8(blob[o])) << 24)",
        "            | (uint32(uint8(blob[o + 1])) << 16)",
        "            | (uint32(uint8(blob[o + 2])) << 8)",
        "            | uint32(uint8(blob[o + 3]));",
        "        return int256(int32(raw));",
        "    }",
        "",
        "    function data(string memory arm) internal pure returns (bytes memory) {",
        "        bytes32 k = keccak256(bytes(arm));",
    ] + [f'        if (k == keccak256("{a}")) return {a}_DATA;' for a in ARMS] + [
        '        revert("unknown arm");',
        "    }",
        "}",
    ]
    io.open("test/ArmData.sol", "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    print("wrote test/ArmData.sol")


if __name__ == "__main__":
    main()
